import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container for the node
  const root = new Group();

  // Use the aspect ratio of the source image (512 / 320 = 1.6)
  const width = 1.6;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load the texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Empty handler container (no interactions specified)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    if (material.map) material.map.dispose();
    material.dispose();

    // Kill any GSAP timelines that might have been created inadvertently
    gsap.globalTimeline.clear();
  };

  return root;
}
